import{_ as i,a0 as p,w as l,s as u,I as s,x as e,a1 as n,A as r,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"使用 Linux 自動化工具提高生產率 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 自動化工具提高生產率 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 自動化工具提高生產率 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 自動化工具提高生產率 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210203 Improve your productivity with this Linux automation tool","title":"使用 Linux 自動化工具提高生產率","tag":"202104","desc":""},"relativePath":"202104/20210203 Improve your productivity with this Linux automation tool.md","filePath":"[post].md"}'),d={name:"202104/20210203 Improve your productivity with this Linux automation tool.md"};function y(b,t,g,k,f,m){const a=p("Link");return l(),u("div",null,[t[38]||(t[38]=s("h1",{id:"使用-linux-自動化工具提高生產率",tabindex:"-1"},[e("使用 Linux 自動化工具提高生產率 "),s("a",{class:"header-anchor",href:"#使用-linux-自動化工具提高生產率","aria-label":"Permalink to “使用 Linux 自動化工具提高生產率”"},"​")],-1)),t[39]||(t[39]=s("blockquote",null,[s("p",null,"用 AutoKey 配置你的鍵盤，糾正常見的錯別字，輸入常用的短語等等。")],-1)),t[40]||(t[40]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202104/30/111130s7ffji6cmb7rkcfx.jpg",alt:""})],-1)),s("p",null,[n(a,{href:"https://github.com/autokey/autokey"},{default:r(()=>[...t[0]||(t[0]=[e("AutoKey",-1)])]),_:1}),t[1]||(t[1]=e(" 是一個開源的 Linux 桌面自動化工具，一旦它成為你工作流程的一部分，你就會想，如何沒有它，那該怎麼辦。它可以成為一種提高生產率的變革性工具，或者僅僅是減少與打字有關的身體壓力的一種方式。",-1))]),t[41]||(t[41]=s("p",null,"本文將研究如何安裝和開始使用 AutoKey ，介紹一些可以立即在工作流程中使用的簡單方法，並探討 AutoKey 高級用户可能會感興趣的一些高級功能。",-1)),t[42]||(t[42]=s("h3",{id:"安裝並設置-autokey",tabindex:"-1"},[e("安裝並設置 AutoKey "),s("a",{class:"header-anchor",href:"#安裝並設置-autokey","aria-label":"Permalink to “安裝並設置 AutoKey”"},"​")],-1)),s("p",null,[t[3]||(t[3]=e("AutoKey 在許多 Linux 發行版中都是現成的軟件包。該項目的 ",-1)),n(a,{href:"https://github.com/autokey/autokey/wiki/Installing"},{default:r(()=>[...t[2]||(t[2]=[e("安裝指南",-1)])]),_:1}),t[4]||(t[4]=e(" 包含許多平台的説明，也包括了從源代碼進行構建的指導。本文使用 Fedora 作為操作平台。",-1))]),s("p",null,[t[7]||(t[7]=e("AutoKey 有兩個變體：為像 GNOME 等基於 ",-1)),n(a,{href:"https://www.gtk.org/"},{default:r(()=>[...t[5]||(t[5]=[e("GTK",-1)])]),_:1}),t[8]||(t[8]=e(" 環境而設計的 autokey-gtk 和基於 ",-1)),n(a,{href:"https://www.qt.io/"},{default:r(()=>[...t[6]||(t[6]=[e("QT",-1)])]),_:1}),t[9]||(t[9]=e(" 的 autokey-qt。",-1))]),t[43]||(t[43]=o('<p>你可以從命令列安裝任一變體：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install autokey-gtk</span></span></code></pre></div><p>安裝完成後，使用 <code>autokey-gtk</code>（或 <code>autokey-qt</code>）運行它。</p><h3 id="探究界面" tabindex="-1">探究界面 <a class="header-anchor" href="#探究界面" aria-label="Permalink to “探究界面”">​</a></h3><p>在將 AutoKey 設置為在後台運行並自動執行操作之前，你首先需要對其進行配置。調出用户界面（UI）配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>autokey-gtk -c</span></span></code></pre></div><p>AutoKey 提供了一些預設配置的示例。你可能希望在熟悉 UI 時將他們留作備用，但是可以根據需要刪除它們。</p><p><img src="https://opensource.com/sites/default/files/uploads/autokey-defaults.png" alt="AutoKey 用户界面" title="AutoKey UI"></p><p>左側窗格包含一個文件夾式的短語和腳本的層次結構。“<ruby>短語<rt>Phrases</rt></ruby>” 代表要讓 AutoKey 輸入的文本。“<ruby>腳本<rt>Scripts</rt></ruby>” 是動態的、程序化的等效項，可以使用 Python 編寫，並且獲得與鍵盤擊鍵發送到活動窗口基本相同的結果。</p><p>右側窗格構建和配置短語和腳本。</p><p>對配置滿意後，你可能希望在登錄時自動運行 AutoKey，這樣就不必每次都啓動它。你可以通過在 “<ruby>首選項<rt>Preferences</rt></ruby>”菜單（“<ruby>編輯 -&gt; 首選項<rt>Edit -&gt; Preferences”</rt></ruby>”）中勾選 “<ruby>登錄時自動啓動 AutoKey<rt>Automatically start AutoKey at login</rt></ruby>”進行配置。</p><p><img src="https://opensource.com/sites/default/files/uploads/startautokey.png" alt="登錄時自動啓動 AutoKey" title="Automatically start AutoKey at login"></p><h3 id="使用-autokey-糾正常見的打字排版錯誤" tabindex="-1">使用 AutoKey 糾正常見的打字排版錯誤 <a class="header-anchor" href="#使用-autokey-糾正常見的打字排版錯誤" aria-label="Permalink to “使用 AutoKey 糾正常見的打字排版錯誤”">​</a></h3><p>修復常見的打字排版錯誤對於 AutoKey 來説是一個容易解決的問題。例如，我始終鍵入 “gerp” 來代替 “grep”。這裏是如何配置 AutoKey 為你解決這些類型問題。</p><p>創建一個新的子文件夾，可以在其中將所有“打字排版錯誤校正”配置分組。在左側窗格中選擇 “My Phrases” ，然後選擇 “<ruby>文件 -&gt; 新建 -&gt; 子文件夾<rt>File -&gt; New -&gt; Subfolder</rt></ruby>”。將子文件夾命名為 “Typos”。</p><p>在 “<ruby>文件 -&gt; 新建 -&gt; 短語<rt>File -&gt; New -&gt; Phrase</rt></ruby>” 中創建一個新短語。並將其稱為 “grep”。</p><p>通過高亮選擇短語 “grep”，然後在 <ruby>輸入短語內容<rt>Enter phrase contents</rt></ruby>部分（替換默認的 “Enter phrase contents” 文本）中輸入 “grep” ，配置 AutoKey 插入正確的關鍵詞。</p><p>接下來，通過定義縮寫來設置 AutoKey 如何觸發此短語。點擊用户界面底部緊鄰 “<ruby>縮寫<rt>Abbreviations</rt></ruby>” 的 “<ruby>設置<rt>Set</rt></ruby>”按鈕。</p><p>在彈出的對話框中，單擊 “<ruby>添加<rt>Add</rt></ruby>” 按鈕，然後將 “gerp” 添加為新的縮寫。勾選 “<ruby>刪除鍵入的縮寫<rt>Remove typed abbreviation</rt></ruby>”；此選項讓 AutoKey 將任何鍵入 “gerp” 一詞的替換為 “grep”。請不要勾選“<ruby>在鍵入單詞的一部分時觸發<rt>Trigger when typed as part of a word</rt></ruby>”，這樣，如果你鍵入包含 “grep”的單詞（例如 “fingerprint”），就不會嘗試將其轉換為 “fingreprint”。僅當將 “grep” 作為獨立的單詞鍵入時，此功能才有效。</p><p><img src="https://opensource.com/sites/default/files/uploads/autokey-set_abbreviation.png" alt="在 AutoKey 中設置縮寫" title="Set abbreviation in AutoKey"></p><h3 id="限制對特定應用程序的更正" tabindex="-1">限制對特定應用程序的更正 <a class="header-anchor" href="#限制對特定應用程序的更正" aria-label="Permalink to “限制對特定應用程序的更正”">​</a></h3><p>你可能希望僅在某些應用程序（例如終端窗口）中打字排版錯誤時才應用校正。你可以通過設置 <ruby>窗口過濾器<rt>Window Filter</rt></ruby>進行配置。單擊 “<ruby>設置<rt>Set</rt></ruby>” 按鈕來定義。</p><p>設置<ruby>窗口過濾器<rt>Window Filter</rt></ruby>的最簡單方法是讓 AutoKey 為你檢測窗口類型：</p><ol><li>啓動一個新的終端窗口。</li><li>返回 AutoKey，單擊 “<ruby>檢測窗口屬性<rt>Detect Window Properties</rt></ruby>”按鈕。</li><li>單擊終端窗口。</li></ol><p>這將自動填充窗口過濾器，可能的窗口類值為 <code>gnome-terminal-server.Gnome-terminal</code>。這足夠了，因此單擊 “OK”。</p><p><img src="https://opensource.com/sites/default/files/uploads/autokey-window_filter.png" alt="AutoKey 窗口過濾器" title="AutoKey Window Filter"></p><h3 id="保存並測試" tabindex="-1">保存並測試 <a class="header-anchor" href="#保存並測試" aria-label="Permalink to “保存並測試”">​</a></h3><p>對新配置滿意後，請確保將其保存。 單擊 “<ruby>文件<rt>File</rt></ruby>” ，然後選擇 “<ruby>保存<rt>Save</rt></ruby>” 以使更改生效。</p><p>現在進行重要的測試！在你的終端窗口中，鍵入 “gerp” 緊跟一個空格，它將自動更正為 “grep”。要驗證窗口過濾器是否正在運行，請嘗試在瀏覽器 URL 欄或其他應用程序中鍵入單詞 “gerp”。它並沒有變化。</p>',29)),s("p",null,[t[11]||(t[11]=e("你可能會認為，使用 ",-1)),n(a,{href:"https://opensource.com/article/19/7/bash-aliases"},{default:r(()=>[...t[10]||(t[10]=[e("shell 別名",-1)])]),_:1}),t[12]||(t[12]=e(" 可以輕鬆解決此問題，我完全贊成！與別名不同，只要是面向命令列，無論你使用什麼應用程序，AutoKey 都可以按規則糾正錯誤。",-1))]),t[44]||(t[44]=o('<p>例如，我在瀏覽器，集成開發環境和終端中輸入的另一個常見打字錯誤 “openshfit” 替代為 “openshift”。別名不能完全解決此問題，而 AutoKey 可以在任何情況下糾正它。</p><h3 id="鍵入常用短語" tabindex="-1">鍵入常用短語 <a class="header-anchor" href="#鍵入常用短語" aria-label="Permalink to “鍵入常用短語”">​</a></h3><p>你可以通過許多其他方法來調用 AutoKey 的短語來幫助你。例如，作為從事 OpenShift 的站點可靠性工程師（SRE），我經常在命令列上輸入 Kubernetes 命名空間名稱：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>oc get pods -n openshift-managed-upgrade-operator</span></span></code></pre></div><p>這些名稱空間是靜態的，因此它們是鍵入特定命令時 AutoKey 可以為我插入的理想短語。</p><p>為此，我創建了一個名為 “Namespaces” 的短語子文件夾，併為我經常鍵入的每個命名空間添加了一個短語條目。</p><h3 id="分配熱鍵" tabindex="-1">分配熱鍵 <a class="header-anchor" href="#分配熱鍵" aria-label="Permalink to “分配熱鍵”">​</a></h3><p>接下來，也是最關鍵的一點，我為子文件夾分配了一個 “<ruby>熱鍵<rt>hotkey</rt></ruby>”。每當我按下該熱鍵時，它都會打開一個菜單，我可以在其中選擇（要麼使用 “方向鍵”+回車鍵要麼使用數字）要插入的短語。這減少了我僅需幾次擊鍵就可以輸入這些命令的擊鍵次數。</p><p>“My Phrases” 文件夾中 AutoKey 的預配置示例使用 <code>Ctrl+F7</code> 熱鍵進行配置。如果你將示例保留在 AutoKey 的默認配置中，請嘗試一下。你應該在此處看到所有可用短語的菜單。使用數字或箭頭鍵選擇所需的項目。</p><h3 id="高級自動鍵入" tabindex="-1">高級自動鍵入 <a class="header-anchor" href="#高級自動鍵入" aria-label="Permalink to “高級自動鍵入”">​</a></h3>',10)),s("p",null,[t[14]||(t[14]=e("AutoKey 的 ",-1)),n(a,{href:"https://autokey.github.io/index.html"},{default:r(()=>[...t[13]||(t[13]=[e("腳本引擎",-1)])]),_:1}),t[15]||(t[15]=e(" 允許用户運行可以通過相同的縮寫和熱鍵系統調用的 Python 腳本。這些腳本可以通過支持的 API 的函數來完成諸如切換窗口、發送按鍵或執行鼠標單擊之類的操作。",-1))]),s("p",null,[t[18]||(t[18]=e("AutoKey 用户非常歡迎這項功能，發佈了自定義腳本供其他用户採用。例如，",-1)),n(a,{href:"https://github.com/luziferius/autokey_scripts"},{default:r(()=>[...t[16]||(t[16]=[e("NumpadIME 腳本",-1)])]),_:1}),t[19]||(t[19]=e(" 將數字鍵盤轉換為舊的手機樣式的文本輸入方法，",-1)),n(a,{href:"https://github.com/AlienKevin/Emojis-AutoKey"},{default:r(()=>[...t[17]||(t[17]=[e("Emojis-AutoKey",-1)])]),_:1}),t[20]||(t[20]=e(" 可以通過將諸如: ",-1)),t[21]||(t[21]=s("code",null,":smile:",-1)),t[22]||(t[22]=e(" 之類的短語轉換為它們等價的表情符號來輕鬆插入。",-1))]),t[45]||(t[45]=o(`<p>這是我設置的一個小腳本，該腳本進入 Tmux 的複製模式，以將前一行中的第一個單詞複製到粘貼緩衝區中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from time import sleep</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 發送 Tmux 命令前綴（b 更改為 s）</span></span>
<span class="line"><span>keyboard.send_keys(&quot;&lt;ctr&gt;+s&quot;)</span></span>
<span class="line"><span># Enter copy mode</span></span>
<span class="line"><span>keyboard.send_key(&quot;[&quot;)</span></span>
<span class="line"><span>sleep(0.01)</span></span>
<span class="line"><span># Move cursor up one line</span></span>
<span class="line"><span>keyboard.send_keys(&quot;k&quot;)</span></span>
<span class="line"><span>sleep(0.01)</span></span>
<span class="line"><span># Move cursor to start of line</span></span>
<span class="line"><span>keyboard.send_keys(&quot;0&quot;)</span></span>
<span class="line"><span>sleep(0.01)</span></span>
<span class="line"><span># Start mark</span></span>
<span class="line"><span>keyboard.send_keys(&quot; &quot;)</span></span>
<span class="line"><span>sleep(0.01)</span></span>
<span class="line"><span># Move cursor to end of word</span></span>
<span class="line"><span>keyboard.send_keys(&quot;e&quot;)</span></span>
<span class="line"><span>sleep(0.01)</span></span>
<span class="line"><span># Add to copy buffer</span></span>
<span class="line"><span>keyboard.send_keys(&quot;\`&lt;Ctrl&gt;\`+m&quot;)</span></span></code></pre></div><p>之所以有 <code>sleep</code> 函數，是因為 Tmux 有時無法跟上 AutoKey 發送擊鍵的速度，並且它們對整體執行時間的影響可忽略不計。</p><h3 id="使用-autokey-自動化" tabindex="-1">使用 AutoKey 自動化 <a class="header-anchor" href="#使用-autokey-自動化" aria-label="Permalink to “使用 AutoKey 自動化”">​</a></h3><p>我希望你喜歡這篇使用 AutoKey 進行鍵盤自動化的探索，它為你提供了有關如何改善工作流程的一些好主意。如果你在使用 AutoKey 時有什麼有用的或新穎的方法，一定要在下面的評論中分享。</p><hr>`,6)),s("p",null,[t[24]||(t[24]=e("via: ",-1)),n(a,{href:"https://opensource.com/article/21/2/linux-autokey"},{default:r(()=>[...t[23]||(t[23]=[e("https://opensource.com/article/21/2/linux-autokey",-1)])]),_:1})]),s("p",null,[t[29]||(t[29]=e("作者：",-1)),n(a,{href:"https://opensource.com/users/mbargenquast"},{default:r(()=>[...t[25]||(t[25]=[e("Matt Bargenquast",-1)])]),_:1}),t[30]||(t[30]=e(" 選題：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[26]||(t[26]=[e("lujun9972",-1)])]),_:1}),t[31]||(t[31]=e(" 譯者：",-1)),n(a,{href:"https://github.com/stevenzdg988"},{default:r(()=>[...t[27]||(t[27]=[e("stevenzdg988",-1)])]),_:1}),t[32]||(t[32]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:r(()=>[...t[28]||(t[28]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[35]||(t[35]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[33]||(t[33]=[e("LCTT",-1)])]),_:1}),t[36]||(t[36]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:r(()=>[...t[34]||(t[34]=[e("Linux中國",-1)])]),_:1}),t[37]||(t[37]=e(" 榮譽推出",-1))])])}const K=i(d,[["render",y]]);export{x as __pageData,K as default};
